import { test, expect } from '@playwright/test';

test.describe('Async Error Retry Option', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/api/data');
  });

  test('should display retry option when async operation fails', async ({ page }) => {
    // Intercept the initial API call and simulate failure
    await page.route('**/api/data', (route) => {
      route.abort('failed');
    });

    // Click the button to trigger the async operation
    const loadButton = page.getByRole('button', { name: /load data/i });
    await loadButton.click();

    // Wait for error message to appear
    const errorMessage = page.getByText(/failed to load data/i);
    await expect(errorMessage).toBeVisible();

    // Verify retry button is visible
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify retry button has correct handler
    await expect(retryButton).toHaveAttribute('data-testid', /retry-button/);

    // Click retry button
    await retryButton.click();

    // Unintercept the API call to allow retry
    await page.unroute('**/api/data');

    // Wait for successful retry
    await page.waitForResponse('**/api/data');

    // Verify success message is displayed
    const successMessage = page.getByText(/data loaded successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify error message is no longer visible
    await expect(errorMessage).not.toBeVisible();
  });

  test('should not display retry option when async operation succeeds', async ({ page }) => {
    // Intercept the API call and simulate success
    await page.route('**/api/data', (route) => {
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({ data: 'test data' }),
      });
    });

    // Click the button to trigger the async operation
    const loadButton = page.getByRole('button', { name: /load data/i });
    await loadButton.click();

    // Wait for success message
    const successMessage = page.getByText(/data loaded successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify retry button does not exist
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).not.toBeVisible();

    // Verify error message does not exist
    const errorMessage = page.getByText(/failed to load data/i);
    await expect(errorMessage).not.toBeVisible();

    // Verify data is displayed
    const dataDisplay = page.getByText('test data');
    await expect(dataDisplay).toBeVisible();
  });
});
